def find_zero(xs: list):
    def f(x):
        return sum(c * x**i for i, c in enumerate(xs))

    a, b = -1.0, 1.0
    while f(a) * f(b) >= 0:
        a -= 2.0
        b += 2.0

    while abs(f(a)) > 1e-10:
        mid = (a + b) / 2
        if f(mid) == 0:
            return mid
        if f(a) * f(mid) < 0:
            b = mid
        else:
            a = mid
    return a
